const e=[{id:"board:coords",level:"Level 1: Das Schachbrett verstehen",title:"Koordinaten und Ausrichtung",teach:[["Acht mal acht","Ein Schachbrett hat 64 Felder in 8 Spalten und 8 Reihen. Die Spalten heißen a bis h (von Weiß aus links nach rechts), die Reihen 1 bis 8 (von unten nach oben aus Sicht von Weiß). Jedes Feld hat dadurch eine eindeutige Adresse, z. B. e4."],["Die goldene Regel",'Merksatz für den Aufbau: „Helles Feld unten rechts." Steht das Brett falsch herum, wirken Analysen aus Büchern verwirrend, weil links und rechts vertauscht erscheinen.'],["Warum das wichtig ist","Jede Zugnotation — egal ob in Büchern, Analysen oder dieser App — basiert auf diesen Koordinaten. Ohne sie bleibt Schachliteratur unzugänglich."]],quiz:[{q:"Welches Feld liegt in der a-Spalte, 1. Reihe?",o:["a1","h1","a8","h8"],c:0}]},{id:"board:setup",level:"Level 1: Das Schachbrett verstehen",title:"Die Grundstellung",teach:[["Die hinterste Reihe","In der Grundstellung stehen auf der 1. (Weiß) bzw. 8. Reihe (Schwarz) von außen nach innen: Turm, Springer, Läufer, Dame, König, Läufer, Springer, Turm."],["Merkregel für die Dame",'„Die Dame steht auf ihrer eigenen Farbe" — die weiße Dame startet auf einem hellen Feld (d1), die schwarze auf einem dunklen (d8).'],["Die Bauernreihe","Direkt davor steht auf der 2. bzw. 7. Reihe eine komplette Reihe Bauern — zahlenmäßig die stärkste, wertmäßig aber die schwächste Einheit."]],quiz:[{q:"Auf welchem Feld steht der schwarze König zu Beginn?",o:["e8","d8","e1","d1"],c:0}]},{id:"board:material",level:"Level 1: Das Schachbrett verstehen",title:"Materialwert der Figuren",teach:[["Die Faustregel","Bauer = 1 Punkt, Springer = 3, Läufer = 3, Turm = 5, Dame = 9. Der König hat keinen Punktwert — er darf nie geschlagen werden, das Spiel endet vorher durch Matt."],["Wofür das gut ist",'Diese Werte helfen, Tauschgeschäfte einzuschätzen: Turm gegen Läufer und Bauer (5 gegen 3+1=4) ist meist leicht ungünstig für die Turmseite — man nennt das ein „Qualitätsopfer".'],["Nur eine Faustregel","Die Werte sind Richtwerte, keine exakte Wissenschaft. Ein hervorragend platzierter Springer kann in bestimmten Stellungen wertvoller sein als ein eingesperrter Läufer."]],quiz:[{q:"Wie viele Bauern ist eine Dame ungefähr wert?",o:["9","3","5","1"],c:0},{q:"Ist ein Turmopfer gegen Läufer+Bauer (5 gegen 4) für die Turmseite meist günstig oder eher leicht ungünstig?",o:["Eher leicht ungünstig","Immer sehr günstig","Bedeutungslos"],c:0}]},{id:"movement:rook-bishop",level:"Level 2: Figurenbewegung",title:"Turm und Läufer",teach:[["Der Turm","Der Turm zieht beliebig weit geradeaus — waagerecht oder senkrecht —, solange kein eigenes Stück im Weg steht. Über Figuren springen kann er nicht."],["Der Läufer",'Der Läufer zieht beliebig weit diagonal. Da er die Feldfarbe nie wechseln kann, bleibt ein Läufer sein ganzes „Leben" lang entweder auf hellen oder auf dunklen Feldern.'],["Gemeinsam stark","Turm und Läufer ergänzen sich gut: Der Turm deckt Reihen und Linien ab, der Läufer die Diagonalen — zusammen praktisch das ganze Brett."]],quiz:[{q:"Kann ein Läufer, der auf einem hellen Feld steht, jemals auf ein dunkles Feld ziehen?",o:["Nein, nie","Ja, nach ein paar Zügen","Nur beim Schlagen"],c:0}]},{id:"movement:knight",level:"Level 2: Figurenbewegung",title:"Der Springer",teach:[["Die L-Form","Der Springer zieht als einzige Figur nicht geradlinig: zwei Felder in eine Richtung, dann ein Feld im rechten Winkel dazu — insgesamt eine L-Form."],["Er springt wirklich","Als einzige Figur darf der Springer über andere Figuren hinwegspringen — ideal, um verstellte Stellungen zu durchbrechen."],["Rand ist schwach",'Merksatz: „Springer am Rand bringt Kummer und Schand." Im Zentrum erreicht ein Springer bis zu 8 Felder, in der Ecke nur 2.']],quiz:[{q:"Wie viele Felder kann ein Springer im Zentrum des Bretts maximal erreichen?",o:["8","4","6","12"],c:0}]},{id:"movement:queen-king",level:"Level 2: Figurenbewegung",title:"Dame und König",teach:[["Die Dame","Die Dame vereint Turm und Läufer: Sie zieht beliebig weit waagerecht, senkrecht und diagonal — die stärkste Figur auf dem Brett."],["Der König","Der König zieht wie die Dame, aber nur ein einziges Feld pro Zug. Trotz seiner Schwäche im Zug ist er die wichtigste Figur — fällt er, ist die Partie vorbei."],["Der König darf sich nie in Gefahr begeben","Ein Zug, nach dem der eigene König im Schach stünde, ist verboten — selbst wenn er sonst legal aussähe."]],quiz:[{q:"Darf der König einen Zug machen, nach dem er im Schach steht?",o:["Nein, das ist nie erlaubt","Ja, das ist normal","Nur wenn er keine andere Wahl hat"],c:0}]},{id:"movement:pawn",level:"Level 2: Figurenbewegung",title:"Der Bauer",teach:[["Vorwärts, nie zurück","Der Bauer zieht als einzige Figur nur in eine Richtung: für Weiß nach oben, für Schwarz nach unten — nie rückwärts."],["Normalzug vs. Schlagzug","Geradeaus zieht der Bauer nur, wenn das Feld frei ist. Schlagen kann er dagegen nur diagonal, ein Feld schräg vorwärts — nie geradeaus."],["Der Doppelschritt","Von seiner Startreihe aus darf ein Bauer einmalig zwei Felder ziehen statt eines — das ermöglicht schnelleres Entwickeln in der Eröffnung."],["Ausblick: En Passant und Umwandlung","Zwei Spezialregeln lernst du in einer späteren Lektion im Detail — die App unterstützt beide schon vollständig im normalen Spiel."]],quiz:[{q:"In welche Richtung darf ein Bauer schlagen?",o:["Nur diagonal, ein Feld vorwärts","Geradeaus wie sein Normalzug","Nach vorne UND hinten"],c:0}]},{id:"checkmate:what-is-check",level:"Level 3: Schach & Schachmatt",title:"Was ist Schach?",teach:[["Definition","Ein König steht im Schach, wenn er von einer gegnerischen Figur angegriffen wird — er könnte also im nächsten Zug geschlagen werden."],["Pflicht zu reagieren","Steht dein König im Schach, MUSST du im selben Zug das Schach beenden. Jeder Zug, der das nicht tut, ist illegal."],["Schach ist nicht das Ende","Schach bedeutet nur eine akute Bedrohung, nicht automatisch das Ende der Partie — es gibt (fast) immer eine Antwort darauf."]],quiz:[{q:"Was MUSST du tun, wenn dein König im Schach steht?",o:["Im selben Zug das Schach beenden","Sofort aufgeben","Den König sofort rochieren"],c:0}]},{id:"checkmate:three-responses",level:"Level 3: Schach & Schachmatt",title:"Drei Antworten auf Schach",teach:[["1. Den König bewegen","Der einfachste Weg: den König auf ein Feld ziehen, das nicht angegriffen wird."],["2. Die angreifende Figur schlagen","Wenn möglich, kannst du die schachbietende Figur einfach vom Brett nehmen."],["3. Das Schach blocken","Bei Fernangriffen (Dame, Turm, Läufer) kannst du eine eigene Figur dazwischenstellen. Das funktioniert NICHT gegen Springerschach — ein Springer springt über blockierende Figuren hinweg."]],quiz:[{q:"Warum kann man ein Springerschach nicht blocken?",o:["Weil der Springer über dazwischenstehende Figuren springt","Weil Springer unsichtbar sind","Man kann es doch blocken"],c:0}]},{id:"checkmate:what-is-mate",level:"Level 3: Schach & Schachmatt",title:"Was ist Schachmatt?",teach:[["Matt = Schach ohne Ausweg","Schachmatt ist ein Schach, aus dem es keine der drei Antworten mehr gibt: Der König kann nicht fliehen, der Angreifer kann nicht geschlagen und das Schach kann nicht geblockt werden."],["Das Spiel endet sofort","Sobald Schachmatt eintritt, ist die Partie sofort vorbei — egal, wie viel Material noch auf dem Brett steht."],["Patt ist etwas anderes","Patt bedeutet: Der Spieler am Zug steht NICHT im Schach, hat aber keinen einzigen legalen Zug. Patt beendet die Partie ebenfalls, aber als Remis (Unentschieden) — nicht als Niederlage!"]],quiz:[{q:"Wie endet eine Partie bei Patt?",o:["Unentschieden (Remis)","Sieg für den Spieler am Zug","Niederlage für den Spieler am Zug"],c:0}]},{id:"checkmate:mate-patterns",level:"Level 3: Schach & Schachmatt",title:"Grundlegende Mattbilder",teach:[["Das Randmatt (Turm)","Ein einzelner Turm kann mit Unterstützung des eigenen Königs einen gegnerischen König an den Brettrand drängen und dort mattsetzen — eines der ersten Endspiele, das man beherrschen sollte."],["Das Erstickungsmatt",'Ein Springer kann einen König mattsetzen, der komplett von eigenen Figuren eingeschlossen ist und sich deshalb nicht bewegen kann — der König „erstickt" an seinen eigenen Figuren.'],["Warum Mattbilder lernen?","Wer typische Mattbilder erkennt, findet gegnerische Mattangriffe viel schneller — Muster wiedererkennen ist eine der wichtigsten Fähigkeiten im Schach überhaupt."]],quiz:[{q:"Wie nennt man ein Matt, bei dem der König von eigenen Figuren eingeschlossen ist?",o:["Erstickungsmatt","Randmatt","Doppelmatt"],c:0}]},{id:"tactics1:fork",level:"Level 4: Grundlegende Taktik",title:"Die Gabel",teach:[["Definition","Eine Gabel liegt vor, wenn eine einzelne Figur gleichzeitig zwei (oder mehr) gegnerische Figuren angreift — der Gegner kann meist nur eine davon retten."],["Der Springer als Gabel-Spezialist","Springer sind besonders gute Gabel-Figuren, weil ihre L-förmigen Sprünge oft zwei weit auseinanderliegende Figuren gleichzeitig treffen, die sich sonst nicht gegenseitig decken können."],["Königsgabel","Besonders stark: eine Gabel, die auch den König mit angreift — dann MUSS der Gegner zuerst das Schach beantworten, und die andere Figur fällt garantiert."]],quiz:[{q:'Warum sind Springer besonders gute „Gabel"-Figuren?',o:["Ihre L-Sprünge treffen oft zwei ungedeckte Figuren gleichzeitig, die sich nicht decken","Sie sind die wertvollste Figur","Sie können nicht geschlagen werden"],c:0}]},{id:"tactics1:pin",level:"Level 4: Grundlegende Taktik",title:"Die Fesselung",teach:[["Definition","Eine Figur ist gefesselt, wenn sie sich nicht bewegen darf oder sollte, weil dahinter eine wertvollere Figur (oft der König) ungedeckt stünde."],["Absolute vs. relative Fesselung","Bei einer absoluten Fesselung steht der König direkt dahinter — der Zug wäre schlicht illegal. Bei einer relativen Fesselung steht nur eine wertvolle Figur (z. B. die Dame) dahinter — der Zug wäre legal, aber taktisch riskant."],["Fesselungen ausnutzen","Eine gefesselte Figur verteidigt schlechter, weil sie sich kaum bewegen kann — oft lohnt es sich, zusätzlichen Druck auf sie aufzubauen."]],quiz:[{q:"Was unterscheidet eine absolute von einer relativen Fesselung?",o:["Bei absolut steht der König dahinter (Zug wäre illegal), bei relativ eine andere wertvolle Figur (Zug wäre nur riskant)","Absolute Fesselungen gibt es nur im Endspiel","Relative Fesselungen sind stärker als absolute"],c:0}]},{id:"tactics1:skewer",level:"Level 4: Grundlegende Taktik",title:"Der Spieß",teach:[["Definition",'Ein Spieß ist quasi die „umgekehrte Fesselung": Eine wertvolle Figur wird angegriffen und muss ausweichen — dahinter kommt eine weniger wertvolle Figur zum Vorschein, die man dann gewinnt.'],["Königsspieß","Am häufigsten sieht man Spieße gegen den König: Er muss dem Schach ausweichen, und die dahinterstehende Figur (oft ein Turm oder eine Dame) wird anschließend geschlagen."],["Unterschied zur Fesselung","Bei der Fesselung ist die wertvollere Figur HINTEN, beim Spieß ist sie VORNE. Beide nutzen dieselbe geometrische Idee — eine Linie mit zwei Figuren hintereinander."]],quiz:[{q:"Was passiert nach dem Königszug in der gezeigten Stellung?",o:["Weiß gewinnt den schwarzen Turm auf e8","Die Partie ist sofort remis","Schwarz gewinnt den weißen Turm"],c:0}]},{id:"tactics1:discovered-attack",level:"Level 4: Grundlegende Taktik",title:"Doppelangriff und Abzugsschach",teach:[["Doppelangriff","Ein Doppelangriff bedroht zwei Ziele gleichzeitig mit unterschiedlichen Figuren oder auf unterschiedliche Weise — der Gegner kann meist nur eine Bedrohung parieren."],["Abzugsschach","Bewegt sich eine Figur zur Seite und gibt dadurch einer dahinterstehenden Figur eine freie Linie zum gegnerischen König, spricht man von Abzugsschach — besonders stark, wenn die ziehende Figur selbst auch noch etwas angreift."],["Warum das so stark ist",'Bei einem Abzugsschach muss der Gegner zuerst das Schach beantworten — die ziehende Figur hat in der Zwischenzeit „kostenlos" Zeit, ihre eigene Drohung auszuführen.']],quiz:[{q:"Warum ist Abzugsschach oft besonders gefährlich?",o:["Der Gegner muss zuerst das Schach beantworten, während die ziehende Figur zusätzlich zuschlägt","Es ist eigentlich harmlos","Es funktioniert nur im Endspiel"],c:0}]},{id:"opening:three-principles",level:"Level 5: Eröffnungsprinzipien",title:"Die drei Eröffnungsprinzipien",teach:[["1. Zentrum kontrollieren","Die vier zentralen Felder (d4, e4, d5, e5) sind am wertvollsten — Figuren dort kontrollieren die meisten anderen Felder. Deshalb beginnen die meisten guten Eröffnungen mit einem Zentrumsbauern: 1.e4 oder 1.d4."],["2. Figuren entwickeln",'Bring in den ersten Zügen Springer und Läufer ins Spiel, bevor du mit einer Figur mehrfach ziehst. Jeder "verlorene" Zug (dieselbe Figur zweimal bewegen, ohne Not) gibt dem Gegner Zeit, selbst aufzuholen.'],["3. König in Sicherheit","Rochiere früh (meist innerhalb der ersten 10 Züge) — ein König in der Mitte des Bretts ist während der ganzen restlichen Eröffnung ein Dauerrisiko."]],quiz:[{q:"Welche Felder gelten als das wertvollste Zentrum?",o:["d4, e4, d5, e5","a1, a8, h1, h8","Alle Felder sind gleich wichtig"],c:0},{q:'Was kostet ein "verlorener Zug" (dieselbe Figur zweimal ziehen ohne Not)?',o:["Entwicklungstempo — der Gegner kommt schneller ins Spiel","Nichts, Zeit spielt keine Rolle","Automatisch die Rochade"],c:0},{q:"Bis wann sollte man in der Regel rochiert haben?",o:["Ungefähr innerhalb der ersten 10 Züge","Erst im Endspiel","Rochade ist unwichtig"],c:0}]},{id:"opening:early-queen",level:"Level 5: Eröffnungsprinzipien",title:"Warum man die Dame nicht zu früh entwickelt",teach:[["Die Versuchung","Die Dame ist die stärkste Figur — ein früher Damenausflug wirkt verlockend, weil sie sofort Drohungen aufbauen kann (siehe Schäfermatt-Falle)."],["Das Problem","Genau weil die Dame so wertvoll ist, MUSS sie jedem Angriff ausweichen — jede kleinere Figur, die die Dame angreift, zwingt sie zum Rückzug und der Gegner gewinnt dabei Entwicklungstempo."],["Die Ausnahme","Ist der Damenzug selbst eine konkrete, unparierbare Drohung (wie beim Schäfermatt), kann er trotzdem richtig sein — die Grundregel gilt für den Normalfall, nicht ausnahmslos."]],quiz:[{q:"Warum wird ein früher Damenzug oft bestraft?",o:["Jede kleinere Figur, die sie angreift, zwingt sie zum teuren Rückzug","Die Dame darf nur einmal pro Partie ziehen","Es ist offiziell verboten"],c:0}]},{id:"opening:pawn-moves",level:"Level 5: Eröffnungsprinzipien",title:"Bauernzüge sparsam einsetzen",teach:[["Bauern verlieren keine Zeit — aber Übertreibung schon","Ein oder zwei Bauernzüge zur Zentrumskontrolle sind normal und gut. Viele zusätzliche Bauernzüge (besonders am Rand) entwickeln aber keine Figur und lassen dich im Wettlauf um Entwicklung zurückfallen."],["Bauernzüge sind unumkehrbar","Anders als Figuren können Bauern nicht zurückziehen — ein unnötiger Bauernzug schwächt manchmal dauerhaft ein Feld oder eine Diagonale, die du nie wieder reparieren kannst."],["Faustregel","Frag dich bei jedem Bauernzug in der Eröffnung: Hilft das wirklich der Zentrumskontrolle oder Figurenentwicklung — oder ziehe ich nur, weil mir gerade nichts Besseres einfällt?"]],quiz:[{q:"Warum sind unnötige Bauernzüge in der Eröffnung riskant?",o:["Sie kosten Entwicklungszeit UND sind unumkehrbar","Bauern dürfen generell nicht in der Eröffnung ziehen","Sie sind völlig harmlos"],c:0}]},{id:"opening:opening-mistakes",level:"Level 5: Eröffnungsprinzipien",title:"Häufige Eröffnungsfehler erkennen",teach:[["Rückblick: Schäfermatt & Narrenmatt","Die beiden ersten Rätsel, die du kennengelernt hast, sind genau solche Eröffnungsfehler: ein zu früher Damenausflug, den Schwarz nicht pariert (Schäfermatt), und geschwächte Diagonalen durch unnötige Randbauernzüge (Narrenmatt)."],["Légals Matt als drittes Beispiel","Auch bei Légals Matt bestraft Weiß eine Gier nach Material (die Dame schlagen) mit einem vorbereiteten Mattangriff — ein Muster, das sich immer wieder zeigt: schnelle Materialgewinne in der Eröffnung sind oft eine Falle."],["Der rote Faden","Fast jeder frühe Fehler verletzt eines der drei Prinzipien: Zentrum vernachlässigt, Entwicklung vernachlässigt, oder König in der Mitte gelassen."]],quiz:[{q:"Was haben Schäfermatt, Narrenmatt und Légals Matt gemeinsam?",o:["Sie bestrafen alle eine Verletzung der Eröffnungsprinzipien","Sie funktionieren nur gegen Anfänger-Engines","Sie brauchen alle über 20 Züge"],c:0}]},{id:"kingsafety:why-castle",level:"Level 6: Königssicherheit",title:"Warum Rochade wichtig ist",teach:[["Zwei Fliegen mit einer Klappe","Rochade bringt den König aus dem gefährlichen Zentrum an den Rand UND aktiviert gleichzeitig einen Turm — der einzige Zug im Schach, der zwei Figuren auf einmal bewegt."],["Der König in der Mitte","Ein König, der in der Mitte bleibt, kann durch geöffnete Linien und Diagonalen von mehreren Seiten gleichzeitig angegriffen werden — genau das nutzen viele Eröffnungsfallen aus."],["Kurz oder lang?","Kurze Rochade (Königsseite) ist meist etwas sicherer und geht schneller: Es müssen nur Läufer und Springer weichen, und der König steht danach hinter den drei dicht beieinanderstehenden Bauern f/g/h am Rand. Die lange Rochade (Damenseite) verlangt, dass auch die Dame weicht; dafür kommt schneller ein Turm ins Zentrum."]],quiz:[{q:"Was macht Rochade so besonders unter allen Schachzügen?",o:["Sie bewegt zwei Figuren (König und Turm) in einem einzigen Zug","Sie ist der einzige Zug, der ein Schach ignorieren darf","Sie darf beliebig oft wiederholt werden"],c:0}]},{id:"kingsafety:pawn-shield",level:"Level 6: Königssicherheit",title:"Der Bauernschild",teach:[["Die Schutzmauer","Nach der kurzen Rochade bilden die Bauern auf f2, g2, h2 (bzw. f7/g7/h7 für Schwarz) eine Schutzmauer vor dem König — jeder dieser Bauern, der ohne triftigen Grund zieht, öffnet eine neue Angriffslinie."],["g2-g3 ist meist am unschädlichsten","Wird doch ein Zug nötig, ist g2-g3 (mit Läufer-Fianchetto) meist die sicherste Wahl — g2-g4 oder h2-h4 reißen dagegen deutlich größere Lücken direkt vor dem König."],["Nicht in Panik geraten","Ein einzelner Bauernzug vor dem eigenen König ist noch keine Katastrophe — gefährlich wird es erst, wenn der Gegner tatsächlich genug Angriffsfiguren hat, um die neue Lücke auszunutzen."]],quiz:[{q:"Welcher Bauernzug vor dem eigenen König gilt meist als am unschädlichsten?",o:["g2-g3","g2-g4","h2-h4"],c:0}]},{id:"kingsafety:open-files",level:"Level 6: Königssicherheit",title:"Offene Linien meiden",teach:[["Türme lieben offene Linien","Eine offene Linie (keine Bauern mehr darauf) ist die Autobahn für gegnerische Türme und Damen — steht dein König auf oder neben einer solchen Linie, ist er potenziell in Gefahr."],["Die h-Linie als Klassiker","Nach kurzer Rochade ist besonders die halboffene g- oder h-Linie gefährlich, wenn der Gegner dort einen Turm postieren oder eine Dame heranführen kann."],["Vorbeugen statt reagieren","Bevor du selbst eine Linie vor deinem König öffnest (z. B. durch einen Bauerntausch), frag dich: Wer bekommt am Ende mehr davon — ich oder mein Gegner?"]],quiz:[{q:"Warum sind offene Linien vor dem eigenen König riskant?",o:["Türme und Damen können darauf ungehindert bis zum König vordringen","Sie sind nur für Springer gefährlich","Offene Linien betreffen nur das Endspiel"],c:0}]},{id:"kingsafety:when-not-castle",level:"Level 6: Königssicherheit",title:"Wann man auf Rochade verzichten sollte",teach:[["Rochade ist keine Pflicht","Rochade ist die Regel, nicht das Gesetz — in manchen Stellungen ist der König in der Mitte oder sogar auf der ursprünglichen Seite tatsächlich sicherer."],["Wenn der Gegner schon dorthin zielt","Hat der Gegner seinen Angriff bereits auf eine Seite ausgerichtet (z. B. Figuren Richtung Königsflügel entwickelt), kann Rochade genau dorthin geradewegs ins Messer laufen."],["Wenige Figuren auf dem Brett","Sind schon viele Figuren getauscht, sinkt die Angriffsgefahr insgesamt — im reinen Endspiel zählt oft ein zentraler, aktiver König mehr als einer am Rand."]],quiz:[{q:"Wann kann Rochade ausnahmsweise riskant statt sicher sein?",o:["Wenn der Gegner seinen Angriff schon genau auf diese Seite ausgerichtet hat","Rochade ist immer ausnahmslos sicher","Nur wenn man bereits verloren hat"],c:0}]},{id:"pawnstructure:isolani",level:"Level 7: Bauernstruktur",title:"Der isolierte Bauer (Isolani)",teach:[["Definition","Ein isolierter Bauer hat auf keiner der beiden Nachbarlinien einen eigenen Bauern mehr — er kann also nie von einem anderen Bauern gedeckt werden, nur noch von Figuren."],["Die Schwäche","Weil nur Figuren ihn decken können, wird ein Isolani oft zum dauerhaften Ziel — besonders im Endspiel, wenn wenige Figuren übrig sind, um ihn zu verteidigen."],["Die Stärke","Vor dem Isolani entsteht meist ein starkes, offenes Feld, und die Linien daneben sind halboffen — ideal für eigene Türme und Springer. Ein Isolani ist deshalb oft ein fairer Tausch: Schwäche gegen Aktivität."]],quiz:[{q:"Warum ist ein isolierter Bauer schwer zu verteidigen?",o:["Er kann nur noch von Figuren gedeckt werden, nie von einem anderen Bauern","Er darf sich nicht mehr bewegen","Isolierte Bauern sind eigentlich unbesiegbar"],c:0}]},{id:"pawnstructure:doubled-pawns",level:"Level 7: Bauernstruktur",title:"Doppelbauern",teach:[["Wie sie entstehen","Doppelbauern entstehen meist durch einen Schlagzug — schlägt ein Bauer zur Seite, landet er auf derselben Linie wie ein eigener Bauer davor oder dahinter."],["Die Schwäche","Zwei Bauern auf derselben Linie können sich nicht mehr gegenseitig decken (Bauern decken nur diagonal) und blockieren sich beim Vorrücken gegenseitig — effektiv sind sie oft weniger wert als zwei getrennte Bauern."],["Nicht immer schlecht","Der Schlagzug, der die Doppelbauern erzeugt, öffnet oft eine Linie für einen eigenen Turm oder verbessert die Kontrolle über wichtige Felder — die Bilanz ist nicht immer negativ."]],quiz:[{q:"Warum können sich Doppelbauern nicht gegenseitig decken?",o:["Bauern decken nur diagonal, nie die eigene Linie geradeaus","Doppelbauern dürfen nicht ziehen","Sie decken sich automatisch, das ist kein Problem"],c:0}]},{id:"pawnstructure:backward-pawn",level:"Level 7: Bauernstruktur",title:"Der rückständige Bauer",teach:[["Definition","Ein rückständiger Bauer hinkt seinen Nachbarbauern hinterher und kann nicht gefahrlos vorrücken, weil das Feld direkt vor ihm von einem gegnerischen Bauern kontrolliert wird."],["Das Loch davor",'Das kontrollierte Feld vor einem rückständigen Bauern wird oft zu einem dauerhaften "Loch" — ein perfektes Feld für einen gegnerischen Springer, der von dort aus nicht durch Bauern vertrieben werden kann.'],["Meist auf halboffener Linie","Rückständige Bauern stehen oft auf einer halboffenen Linie (die Gegenlinie ist schon offen) — das macht sie zusätzlich zum Ziel für gegnerische Türme entlang dieser Linie."]],quiz:[{q:"Was macht das kontrollierte Feld vor einem rückständigen Bauern besonders wertvoll für den Gegner?",o:["Es wird zu einem dauerhaften Loch, ideal für einen gegnerischen Springer","Dort darf nur noch die Dame stehen","Es hat gar keine besondere Bedeutung"],c:0}]},{id:"pawnstructure:outpost",level:"Level 7: Bauernstruktur",title:"Starke Felder und Vorposten",teach:[["Was ein starkes Feld ausmacht",'Ein Feld, das von keinem gegnerischen Bauern mehr angegriffen werden kann, gilt als "stark" — eine Figur dort ist praktisch unangreifbar durch Bauern.'],["Der Springer-Vorposten",'Springer profitieren besonders von starken Feldern mitten im gegnerischen Lager (ein "Vorposten") — von dort greifen sie tief in die gegnerische Stellung, ohne vertrieben werden zu können.'],["Wie man Vorposten schafft","Vorposten entstehen oft genau durch die Schwächen aus dieser Lektion — ein rückständiger Bauer oder getauschte Bauern hinterlassen exakt die Löcher, die ein Springer dann besetzt."]],quiz:[{q:'Wodurch wird ein Feld zu einem "starken Feld"?',o:["Kein gegnerischer Bauer kann es mehr angreifen","Es liegt automatisch in der Brettmitte","Nur wenn dort schon eine Figur steht"],c:0}]},{id:"middlegame:find-a-plan",level:"Level 8: Mittelspiel",title:"Pläne finden statt nur Züge suchen",teach:[["Das Problem des planlosen Spiels",'Ohne Plan sucht man jeden Zug einzeln nach "irgendwas Gutem" — das führt oft zu Zügen, die sich gegenseitig widersprechen, statt gemeinsam auf ein Ziel hinzuarbeiten.'],["Woher ein Plan kommt","Die Bauernstruktur verrät meist den passenden Plan: Hast du eine Bauernmehrheit auf einer Seite, spiele dort auf Vormarsch. Hat der Gegner Schwächen (Isolani, rückständiger Bauer), spiele darauf, sie anzugreifen."],["Ein Plan darf sich ändern","Ein guter Plan ist kein starres Korsett — ändert sich die Stellung (z. B. durch einen Abtausch), darf und sollte sich der Plan mit anpassen."]],quiz:[{q:"Woher lässt sich ein sinnvoller Mittelspielplan oft ableiten?",o:["Aus der Bauernstruktur und den Schwächen des Gegners","Reiner Zufall, Pläne bringen nichts","Man sollte den Plan der Eröffnung strikt nie ändern"],c:0}]},{id:"middlegame:open-files-rooks",level:"Level 8: Mittelspiel",title:"Offene Linien besetzen",teach:[["Türme gehören auf offene Linien","Ein Turm auf einer offenen oder halboffenen Linie kontrolliert viel mehr vom Brett als einer, der hinter eigenen Bauern eingesperrt ist."],["Zuerst besetzen, dann eindringen",'Der klassische Plan: zuerst die offene Linie mit einem Turm (oder beiden, "verdoppelt") besetzen, dann auf der Linie bis in die gegnerische Stellung eindringen (die 7. bzw. 2. Reihe ist dabei besonders wertvoll).'],["Wer zuerst kommt...","Ist eine Linie erst offen, lohnt es sich fast immer, sie als Erster zu besetzen — wer zu spät kommt, findet die Linie schon vom Gegner kontrolliert vor."]],quiz:[{q:"Welche Reihe ist für einen eingedrungenen Turm besonders wertvoll?",o:["Die 7. (bzw. 2.) Reihe, wo viele gegnerische Bauern stehen","Die eigene Grundreihe","Das macht keinen Unterschied"],c:0}]},{id:"middlegame:outposts-middlegame",level:"Level 8: Mittelspiel",title:"Schwache Felder besetzen",teach:[["Rückblick Vorposten","Die starken Felder aus der letzten Lektion sind kein Selbstzweck — im Mittelspiel geht es darum, sie tatsächlich mit einer Figur (meist einem Springer) zu besetzen und von dort Druck aufzubauen."],["Vorbereitung zählt","Bevor eine Figur ein starkes Feld besetzt, lohnt es sich oft, es zusätzlich mit einem eigenen Bauern oder einer weiteren Figur zu decken — so kann der Gegner es nicht durch einen Tausch neutralisieren."],["Tausch des Vorpostens","Oft versucht der Gegner genau den Springer auf dem Vorposten zu tauschen (z. B. mit dem eigenen Läufer) — manchmal lohnt es sich, diesen Tausch zu vermeiden und stattdessen auszuweichen."]],quiz:[{q:"Was kann man tun, damit ein starkes Feld nicht durch einen Tausch neutralisiert wird?",o:["Es zusätzlich selbst decken, bevor man es besetzt","Es sofort wieder verlassen","Nichts, das lässt sich nie verhindern"],c:0}]},{id:"middlegame:when-to-trade",level:"Level 8: Mittelspiel",title:"Abtausch bewerten",teach:[["Bei Materialvorteil vereinfachen","Bist du im Vorteil (mehr Material), lohnt sich meist der Tausch von Figuren (nicht Bauern!) — weniger Figuren auf dem Brett bedeuten weniger gegnerische Gegenchancen, während dein Materialvorteil relativ größer wird."],["Bei Rückstand Figuren behalten","Bist du im Rückstand, ist meist das Gegenteil richtig: Figuren auf dem Brett behalten, um Komplikationen und Gegenchancen zu erhalten — im vereinfachten Endspiel wird ein Materialrückstand oft nur noch deutlicher."],["Die eigene schlechte Figur tauschen",'Hast du eine schlecht platzierte Figur (z. B. einen "schlechten" Läufer, der von eigenen Bauern blockiert wird), ist ein Tausch gegen die entsprechende gegnerische Figur oft die beste Lösung.']],quiz:[{q:"Was ist bei einem Materialvorteil meist die richtige Strategie?",o:["Figuren tauschen, um Gegenchancen zu reduzieren","Unbedingt alle Figuren auf dem Brett behalten","Sofort alle Bauern tauschen"],c:0}]},{id:"endgame:opposition",level:"Level 9: Endspiele",title:"Die Opposition",teach:[["Definition",'Zwei Könige stehen sich "in Opposition" gegenüber, wenn zwischen ihnen genau ein Feld frei ist (auf derselben Linie, Reihe oder Diagonale). Wer NICHT am Zug ist, hat die Opposition — und damit meist den Vorteil.'],["Warum das wichtig ist","Der König am Zug muss zwangsweise zurückweichen oder zur Seite ausweichen, während der andere König Boden gutmachen oder einen eigenen Bauern zum Erfolg führen kann."],["Die Falle für Anfänger",'Im Bauernendspiel reicht oft nicht "der König ist näher dran" — wer die Opposition verliert, kann einen eigentlich gewonnenen Bauern manchmal nicht mehr durchbringen.']],quiz:[{q:"Wer hat bei der Opposition typischerweise den Vorteil?",o:["Wer NICHT am Zug ist","Wer am Zug ist","Das ist immer bedeutungslos"],c:0}]},{id:"endgame:square-rule",level:"Level 9: Endspiele",title:"Die Regel des Quadrats",teach:[["Die Faustregel","Um schnell zu erkennen, ob ein gegnerischer König einen weit fortgeschrittenen Bauern noch einholen kann, zieht man gedanklich ein Quadrat vom Bauern bis zu seinem Umwandlungsfeld — steht der König bei seinem Zug innerhalb dieses Quadrats, fängt er den Bauern noch ein."],["Warum das funktioniert","Ein König braucht für jede Reihe genau einen Zug, ein Bauer für jedes Feld ebenfalls einen (Doppelschritt nur vom Start aus) — das Quadrat macht diesen Wettlauf auf einen Blick sichtbar, ohne jeden Zug einzeln durchzurechnen."],["Am Zug denken!","Wer am Zug ist, zählt zuerst — steht der König GENAU auf der Quadratlinie und ist der Bauer am Zug, entkommt der Bauer meist knapp."]],quiz:[{q:"Wozu dient die Regel des Quadrats?",o:["Schnell erkennen, ob ein König einen Bauern noch einholen kann, ohne jeden Zug durchzurechnen","Um zu bestimmen, wer die Eröffnung gewinnt","Sie gilt nur für Läufer, nicht für Bauern"],c:0}]},{id:"endgame:passed-pawn",level:"Level 9: Endspiele",title:"Der Freibauer",teach:[["Definition","Ein Freibauer (passierter Bauer) hat auf seiner eigenen und den beiden Nachbarlinien keinen gegnerischen Bauern mehr vor sich — nichts kann ihn also noch auf dem Weg zur Umwandlung blockieren, außer Figuren."],["Warum Freibauern so wertvoll sind","Je weiter das Endspiel fortschreitet und je weniger Figuren übrig sind, desto gefährlicher wird ein Freibauer — im reinen Bauernendspiel entscheidet oft allein er die Partie."],["Freibauern brauchen Unterstützung","Ein Freibauer allein reicht selten — meist muss der eigene König oder eine Figur ihn auf dem letzten Stück zur Umwandlung begleiten und beschützen."]],quiz:[{q:'Was macht einen Bauern zu einem "Freibauer"?',o:["Kein gegnerischer Bauer auf seiner oder den beiden Nachbarlinien steht ihm noch im Weg","Er hat schon die Umwandlungsreihe erreicht","Er wurde einmal freigekauft"],c:0}]},{id:"endgame:rook-endgame-basics",level:"Level 9: Endspiele",title:"Grundlegendes Turmendspiel",teach:[["Der Turm gehört hinter den Freibauern","Faustregel: Ein Turm gehört immer hinter einen Freibauern — egal ob es der eigene oder der gegnerische ist. Hinter dem eigenen Freibauern unterstützt er den Vormarsch, hinter dem gegnerischen bremst er ihn von hinten aus."],["Türme lieben Aktivität","Im Turmendspiel zählt aktive Turmstellung fast mehr als ein Bauer extra — ein passiver Turm, der nur verteidigt, ist oft schlechter als ein aktiver Turm mit einem Bauern weniger."],["Türme gehören generell selten passiv","Wenn möglich, sollte ein Turm im Endspiel nie nur eine Figur bewachen — besser ist es, aktiv Schach zu bieten oder in die gegnerische Stellung einzudringen."]],quiz:[{q:"Wo sollte ein Turm relativ zu einem Freibauern stehen?",o:["Hinter ihm — egal ob eigener oder gegnerischer Freibauer","Immer direkt daneben","Das spielt überhaupt keine Rolle"],c:0}]},{id:"calculation:candidate-moves",level:"Level 10: Berechnung",title:"Kandidatenzüge finden",teach:[["Nicht den ersten guten Zug spielen",'Statt sofort den ersten vielversprechenden Zug zu spielen, sammle zunächst mehrere "Kandidatenzüge" — echte Alternativen, die du ernsthaft in Betracht ziehst.'],["Woher Kandidaten kommen","Gute Kandidatenzüge findest du meist unter: Schachgebote, Schlagzügen, Drohungen, und Zügen, die eine deiner schlecht platzierten Figuren verbessern."],["Erst sammeln, dann vergleichen","Hast du 2-3 Kandidaten gefunden, rechne jeden einzeln ein Stück durch und vergleiche die Ergebnisse — das verhindert, dass du dich in nur einer Variante verrennst."]],quiz:[{q:"Was sind gute Quellen für Kandidatenzüge?",o:["Schachgebote, Schlagzüge, Drohungen und Verbesserung schlechter Figuren","Nur der erste Zug, der einem einfällt","Ausschließlich Bauernzüge"],c:0}]},{id:"calculation:forcing-first",level:"Level 10: Berechnung",title:"Forcierte Züge zuerst berechnen",teach:[['Was "forciert" bedeutet','Schachgebote, Schlagzüge und konkrete Drohungen lassen dem Gegner kaum Auswahl an Antworten — solche "forcierten" Züge sind am einfachsten zu berechnen, weil du fast genau weißt, was folgt.'],["Reihenfolge beim Rechnen","Prüfe forcierte Möglichkeiten immer zuerst — sie sind oft der Ausgangspunkt für taktische Kombinationen (siehe Gabel, Fesselung, Spieß, Abzugsschach aus dem Taktik-Level)."],["Erst wenn nichts Forciertes funktioniert","Findest du keinen erzwingenden Weg, wechselst du zu ruhigeren, planbasierten Zügen (siehe Level Mittelspiel) — Berechnung und Planung ergänzen sich."]],quiz:[{q:"Warum sollte man forcierte Züge (Schach, Schlag, Drohung) zuerst prüfen?",o:["Sie lassen dem Gegner kaum Auswahl und sind dadurch leichter zu berechnen","Sie sind immer die schlechteste Wahl","Nur Anfänger prüfen forcierte Züge"],c:0}]},{id:"calculation:calculate-to-quiet",level:"Level 10: Berechnung",title:"Bis zur ruhigen Stellung rechnen",teach:[["Das Problem des Abbrechens","Ein häufiger Fehler: mitten in einer forcierten Variante aufhören zu rechnen, weil die Stellung gerade gut aussieht — aber der Gegner hat oft noch ein Zwischenschach oder eine Fesselung parat."],["Die Faustregel",'Rechne eine Variante möglichst bis zu einer wirklich "ruhigen" Stellung durch — keine Schachgebote, keine unmittelbaren Schlagmöglichkeiten mehr für beide Seiten.'],["Wenn es zu komplex wird","Wird eine Variante zu verzweigt, um sie komplett zu Ende zu rechnen, hilft oft eine grobe Einschätzung am Ende: Wer hat mehr Material, wessen König ist sicherer, wer hat die aktiveren Figuren?"]],quiz:[{q:"Warum ist es riskant, eine Variante mitten in einer forcierten Sequenz abzubrechen?",o:["Der Gegner hat oft noch eine Zwischenmöglichkeit, die alles ändert","Das ist überhaupt nicht riskant","Man sollte nie mehr als einen Zug vorausrechnen"],c:0}]},{id:"calculation:check-yourself",level:"Level 10: Berechnung",title:"Rückwärts prüfen",teach:[["Die stärkste Gegenantwort suchen","Nachdem du eine Variante durchgerechnet hast, geh sie noch einmal durch — aber diesmal aus Sicht deines Gegners: Was ist SEIN stärkster Zug an jeder Stelle, nicht nur ein bequemer?"],["Der häufigste Rechenfehler","Die meisten Berechnungsfehler entstehen nicht durch falsche eigene Züge, sondern weil man die beste gegnerische Antwort übersehen oder unterschätzt hat."],["Eine letzte Sicherheitsfrage",'Bevor du den ersten Zug einer berechneten Variante tatsächlich spielst, frag dich: "Was übersehe ich gerade?" — diese eine Frage verhindert erstaunlich viele Blunder.']],quiz:[{q:"Woher entstehen die meisten Berechnungsfehler laut dieser Lektion?",o:["Man übersieht oder unterschätzt die stärkste gegnerische Antwort","Man rechnet grundsätzlich zu viele Züge voraus","Aus fehlerhafter Notation"],c:0}]},{id:"positional:good-bad-pieces",level:"Level 11: Positionsverständnis",title:"Gute und schlechte Figuren",teach:[["Nicht jede Figur ist gleich viel wert",'Zwei Läufer haben denselben Materialwert, aber ein Läufer, der von eigenen Bauern eingesperrt ist, ist "schlecht" — einer mit freien Diagonalen und vielen Zielfeldern ist "gut", selbst wenn beide auf dem Papier 3 Punkte wert sind.'],["Aktivität schlägt oft Statistik",'Eine aktiv postierte, gut platzierte Figur beeinflusst die Partie oft mehr als der reine Materialwert vermuten lässt — deshalb lohnt es sich, bei jeder eigenen Figur zu fragen: "Was tut sie hier eigentlich?"'],["Schlechte Figuren verbessern","Erkennst du eine eigene schlecht platzierte Figur, ist ein Plan, sie zu verbessern (umzuziehen, zu tauschen, oder ihr neue Diagonalen/Linien zu öffnen) oft wertvoller als ein Angriff mit den ohnehin schon guten Figuren."]],quiz:[{q:'Woran erkennt man eine "schlechte" Figur, obwohl ihr Materialwert normal ist?',o:["Sie hat wenig Bewegungsfreiheit/Zielfelder, oft durch eigene Bauern blockiert","Sie steht auf einem hellen Feld","Sie wurde erst kürzlich gezogen"],c:0}]},{id:"positional:bishop-pair",level:"Level 11: Positionsverständnis",title:"Der Läuferpaar-Vorteil",teach:[["Warum zwei Läufer besonders sind","Ein einzelner Läufer erreicht nur die Hälfte aller Felder (nur eine Feldfarbe) — zwei Läufer zusammen decken das komplette Brett ab und ergänzen sich dadurch besonders gut."],["Wann der Vorteil am größten ist","Das Läuferpaar wirkt am stärksten in offenen Stellungen mit wenigen Bauern im Weg — je freier die Diagonalen, desto mehr Reichweite haben beide Läufer gleichzeitig."],["Ein Läufer für einen Springer","Deshalb gilt: Wer sein Läuferpaar unnötig gegen Springer eintauscht, gibt oft einen kleinen, aber echten Vorteil auf — nicht immer entscheidend, aber der Grund, warum starke Spieler das Läuferpaar meist ungern hergeben."]],quiz:[{q:"Warum ergänzen sich zwei Läufer besonders gut?",o:["Zusammen decken sie beide Feldfarben ab, ein einzelner Läufer nur eine","Zwei Läufer dürfen doppelt so weit ziehen","Das Läuferpaar ist nur im Endspiel relevant"],c:0}]},{id:"positional:space-advantage",level:"Level 11: Positionsverständnis",title:"Raumvorteil",teach:[["Was Raumvorteil bedeutet","Wer seine Bauern weiter ins gegnerische Terrain vorgeschoben hat, kontrolliert mehr Felder und hat mehr Platz, um seine Figuren zu manövrieren — das nennt man Raumvorteil."],["Die Kehrseite: weniger Rückzugsräume","Weit vorgeschobene Bauern lassen sich manchmal auch schwerer verteidigen und bieten dem Gegner Angriffsziele — Raumvorteil ist eine Chance, kein automatischer Gewinn."],["Der eingeengte Gegner","Wer wenig Raum hat, tut sich oft schwer, seine eigenen Figuren überhaupt sinnvoll zu entwickeln — manchmal lohnt sich für die beengte Seite ein befreiender Bauerntausch, um wieder Platz zu schaffen."]],quiz:[{q:"Was kann die eingeengte Seite gegen einen gegnerischen Raumvorteil tun?",o:["Einen befreienden Bauerntausch suchen, um wieder Platz zu schaffen","Nichts, Raumvorteil ist immer entscheidend","Sofort aufgeben"],c:0}]},{id:"positional:static-dynamic",level:"Level 11: Positionsverständnis",title:"Statische und dynamische Vorteile",teach:[["Statische Vorteile","Manche Vorteile bleiben über viele Züge bestehen: eine dauerhafte Bauernschwäche beim Gegner (Isolani, rückständiger Bauer), das Läuferpaar, oder eine bessere Bauernstruktur — sie verschwinden nicht von selbst."],["Dynamische Vorteile","Andere Vorteile sind flüchtig: ein Entwicklungsvorsprung, ein Zeitgewinn, oder eine kurzfristig aktivere Stellung — sie müssen schnell genutzt werden, bevor der Gegner aufholt."],["Die richtige Strategie wählen","Bei dynamischem Vorteil lohnt sich oft schnelles, forsches Spiel (den Vorteil ausnutzen, bevor er verschwindet); bei statischem Vorteil kann man sich mehr Zeit lassen — er läuft nicht weg."]],quiz:[{q:"Was unterscheidet einen dynamischen von einem statischen Vorteil?",o:["Dynamische Vorteile sind flüchtig und müssen schnell genutzt werden, statische bleiben bestehen","Es gibt keinen Unterschied","Statische Vorteile verschwinden immer nach 10 Zügen"],c:0}]},{id:"advanced-tactics:zwischenzug",level:"Level 12: Fortgeschrittene Taktik",title:"Der Zwischenzug",teach:[["Definition",'Ein Zwischenzug ("Zwischenzug", international oft "in-between move" genannt) ist ein unerwarteter, meist forcierter Zug, der eingeschoben wird, BEVOR eine eigentlich naheliegende Fortsetzung (z. B. ein Rückschlag) gespielt wird.'],["Warum er so stark ist",'Der Zwischenzug nutzt aus, dass der Gegner zuerst auf eine neue, dringendere Bedrohung reagieren muss — die "eigentliche" Fortsetzung wartet einfach, während der Zwischenzug zusätzlichen Gewinn einbringt.'],["Worauf man achten sollte","Bevor du automatisch zurückschlägst oder die naheliegende Fortsetzung spielst, frag dich immer: Gibt es hier ein stärkeres Schach, einen Schlag oder eine Drohung, die ich zuerst einschieben kann?"]],quiz:[{q:"Was macht einen Zwischenzug taktisch wertvoll?",o:["Der Gegner muss zuerst auf die neue Bedrohung reagieren, bevor er die naheliegende Fortsetzung spielen kann","Er ist einfach nur ein zufälliger zusätzlicher Zug","Zwischenzüge sind nur in der Eröffnung relevant"],c:0}]},{id:"advanced-tactics:combined-motifs",level:"Level 12: Fortgeschrittene Taktik",title:"Kombinationen mit mehreren Motiven",teach:[["Taktik kommt selten allein","In echten Partien treten die Grundmotive aus Level 4 (Gabel, Fesselung, Spieß, Abzugsschach) oft kombiniert auf — eine Fesselung macht z. B. eine Figur erst zum Ziel einer nachfolgenden Gabel."],["Schrittweise denken","Bei komplexen Kombinationen hilft es, sie in ihre Einzelmotive zu zerlegen: Welches Motiv kommt zuerst? Was ermöglicht der erste Zug für den zweiten?"],["Übung schärft den Blick","Je mehr einzelne Motive du sicher erkennst, desto leichter fällt es, sie in Kombination wiederzuerkennen — genau deshalb lohnt sich regelmäßiges Taktiktraining (siehe die Taktik-Rätsel)."]],quiz:[{q:"Warum hilft es, eine komplexe Kombination in Einzelmotive zu zerlegen?",o:["Man erkennt leichter, welches Motiv den nächsten Schritt erst ermöglicht","Kombinationen bestehen nie aus mehreren Motiven","Das Zerlegen macht es komplizierter, nicht einfacher"],c:0}]},{id:"advanced-tactics:sacrifice",level:"Level 12: Fortgeschrittene Taktik",title:"Opferkombinationen",teach:[["Was ein Opfer ausmacht","Bei einer Opferkombination gibst du bewusst Material ab, um dafür etwas Wichtigeres zu bekommen — meist einen Angriff, eine entscheidende Stellung, oder direktes Matt."],["Die entscheidende Frage",'Ein Opfer lohnt sich nur, wenn die Kompensation konkret berechenbar ist (siehe Level Berechnung) — "es fühlt sich stark an" reicht nicht, du solltest die folgenden Züge tatsächlich durchrechnen können.'],["Bekannte Opfermotive","Klassische Muster sind das Läuferopfer auf h7/h2 gegen den rochierten König, oder ein Damenopfer, das zu einem erzwungenen Matt mit den restlichen Figuren führt."]],quiz:[{q:"Wann lohnt sich eine Opferkombination?",o:['Wenn die Kompensation dafür konkret berechenbar ist, nicht nur "gefühlt" stark',"Materialopfer lohnen sich grundsätzlich nie","Nur wenn man bereits gewonnen hat"],c:0}]},{id:"advanced-tactics:pattern-training",level:"Level 12: Fortgeschrittene Taktik",title:"Mustererkennung trainieren",teach:[["Warum Muster wichtiger sind als Berechnung","Starke Spieler berechnen oft gar nicht jeden Zug neu — sie erkennen eine Stellung wieder, weil sie einem bekannten Muster ähnelt, und wissen dadurch sofort, wonach sie suchen müssen."],["Wie man Mustererkennung aufbaut","Das entsteht durch wiederholtes Lösen taktischer Aufgaben — je mehr Muster du gesehen hast, desto schneller erkennst du sie in neuen, unbekannten Stellungen wieder."],["Der Bogen zurück zum Rätsel-Modus","Genau dafür ist der Taktik-Rätsel-Bereich da: nicht um einzelne Aufgaben auswendig zu lernen, sondern um die dahinterliegenden Muster so oft zu sehen, bis du sie automatisch erkennst."]],quiz:[{q:"Wie bauen starke Spieler ihre Mustererkennung auf?",o:["Durch wiederholtes Lösen taktischer Aufgaben","Durch reines Auswendiglernen von Eröffnungszügen","Mustererkennung lässt sich nicht trainieren"],c:0}]},{id:"strategy:attack-wing",level:"Level 13: Strategie",title:"Angriff auf dem richtigen Flügel",teach:[["Die Grundregel","Greife auf der Seite an, auf der du mehr Raum, mehr Figuren oder eine bessere Bauernstruktur hast — ein Angriff dort, wo der Gegner stärker steht, scheitert meist."],["König und Angriff trennen","Hat der Gegner kurz rochiert, ist ein Angriff auf dem Damenflügel oft sicherer für dich selbst, weil du dabei nicht zwangsläufig deinen eigenen König öffnest."],["Nicht auf beiden Seiten gleichzeitig","Ein häufiger Anfängerfehler ist es, auf beiden Flügeln gleichzeitig aktiv zu werden — das verteilt die eigenen Kräfte, statt sie dort zu bündeln, wo sie wirklich etwas bewirken."]],quiz:[{q:"Auf welcher Seite sollte man laut Grundregel angreifen?",o:["Dort, wo man mehr Raum/Figuren/bessere Struktur hat","Immer auf der Königsseite","Immer dort, wo der Gegner stärker steht"],c:0}]},{id:"strategy:prophylaxis",level:"Level 13: Strategie",title:"Prophylaxe — Gegnerpläne verhindern",teach:[["Definition",'Prophylaxe bedeutet, nicht nur den eigenen Plan zu verfolgen, sondern sich zu fragen: "Was will mein Gegner als Nächstes erreichen — und wie verhindere ich das?"'],["Warum das oft übersehen wird","Anfänger konzentrieren sich meist nur auf die eigene Idee und übersehen dabei, dass der Gegner ebenfalls einen Plan verfolgt — ein rein eigener, noch so guter Plan nützt wenig, wenn der Gegner zuerst fertig wird."],["Ein einfacher Prophylaxe-Check",'Bevor du deinen eigenen Zug spielst, frag kurz: "Wenn ich jetzt passen könnte — was würde mein Gegner als Nächstes spielen?" Das verrät oft, welche gegnerische Idee du gerade noch bremsen solltest.']],quiz:[{q:"Was ist die Kernfrage der Prophylaxe?",o:["Was will mein Gegner als Nächstes erreichen, und wie verhindere ich das?","Wie kann ich möglichst schnell Material gewinnen?","Welche Eröffnung soll ich als Nächstes lernen?"],c:0}]},{id:"strategy:good-bad-bishop-strategy",level:"Level 13: Strategie",title:"Den schlechten Läufer angreifen",teach:[["Rückblick: gute und schlechte Figuren",'Du kennst bereits das Konzept eines "schlechten" Läufers, der von eigenen Bauern eingesperrt ist — strategisch geht es jetzt darum, aktiv GEGEN diese Schwäche zu spielen.'],["Die eigene Bauernstruktur danach ausrichten","Stellst du fest, dass der gegnerische Läufer schlecht steht, lohnt es sich oft, die eigene Bauernstruktur so zu wählen, dass genau die Feldfarbe seines Läufers dauerhaft blockiert bleibt."],["Tauschangebote klug einsetzen","Manchmal lohnt es sich sogar, den eigenen (vielleicht sogar besseren) Läufer gegen den schlechten gegnerischen zu tauschen, wenn dadurch die verbleibende Stellung strategisch klar zu deinen Gunsten steht."]],quiz:[{q:"Wie kann man einen schlechten gegnerischen Läufer strategisch ausnutzen?",o:["Die eigene Bauernstruktur so wählen, dass seine Feldfarbe dauerhaft blockiert bleibt","Ihn einfach ignorieren, das lohnt sich nie","Sofort alle eigenen Läufer tauschen"],c:0}]},{id:"strategy:initiative",level:"Level 13: Strategie",title:"Die Initiative behalten",teach:[["Was Initiative bedeutet","Wer die Initiative hat, zwingt den Gegner dazu, auf die eigenen Drohungen zu reagieren, statt selbst aktiv zu werden — der Gegner verteidigt sich nur noch, statt eigene Pläne zu verfolgen."],["Warum Initiative wertvoll ist","Solange du die Initiative hältst, muss der Gegner ständig auf DEINE Ideen antworten — das lässt ihm kaum Zeit, eigene Schwächen zu beheben oder Gegenspiel aufzubauen."],["Initiative kann Material aufwiegen","Ein kleiner Materialnachteil ist oft völlig akzeptabel, solange man dafür die Initiative behält — deshalb sind viele Opferkombinationen aus Level 12 überhaupt erst sinnvoll."]],quiz:[{q:"Warum kann Initiative sogar einen kleinen Materialnachteil aufwiegen?",o:["Der Gegner muss ständig reagieren und kommt nicht zu eigenen Plänen","Material spielt im Schach grundsätzlich keine Rolle","Initiative und Material haben nichts miteinander zu tun"],c:0}]},{id:"opening-deep:opening-types",level:"Level 14: Eröffnungsverständnis",title:"Offene, halboffene und geschlossene Eröffnungen",teach:[["Offene Spiele",'Antwortet Schwarz auf 1.e4 mit 1...e5, entsteht meist eine "offene" Stellung mit früh getauschten Zentrumsbauern, offenen Linien und schnellem Figurenspiel — taktisch oft schärfer.'],["Halboffene Spiele","Antwortet Schwarz auf 1.e4 mit etwas anderem als 1...e5 (z. B. 1...c5, die Sizilianische Verteidigung, oder 1...e6, Französisch), bleibt die Bauernstruktur asymmetrischer — oft komplexere, längerfristige Pläne."],["Geschlossene Spiele","Beginnt die Partie mit 1.d4 d5 oder ähnlichen Zentrumsbauernzügen ohne frühen Tausch, bleibt das Zentrum länger verschlossen — hier zählen Bauernstruktur und langfristige Pläne oft mehr als schnelle Taktik."]],quiz:[{q:'Was ist typisch für eine "geschlossene" Eröffnung?',o:["Das Zentrum bleibt länger verschlossen, langfristige Pläne zählen mehr als schnelle Taktik","Es gibt sofort einen Bauerntausch im Zentrum","Geschlossene Eröffnungen sind immer schneller entschieden"],c:0}]},{id:"opening-deep:tempo-value",level:"Level 14: Eröffnungsverständnis",title:"Der Wert von Tempo",teach:[["Tempo = Zeit in Zügen",'Ein "Tempo" ist im Grunde ein Zug Zeitvorsprung — wer mit weniger eigenen Zügen dieselbe Entwicklung erreicht wie der Gegner, hat effektiv Zeit gewonnen.'],["Wie man Tempo gewinnt","Zieht der Gegner eine Figur zweimal (z. B. weil sie angegriffen wurde), während du in der Zwischenzeit eine neue Figur entwickelst, hast du effektiv ein Tempo gewonnen."],["Tempo in konkrete Vorteile ummünzen","Gewonnene Tempi sind nur wertvoll, wenn du sie nutzt — für schnellere Entwicklung, frühere Rochade, oder einen Angriff, bevor der Gegner aufholen kann."]],quiz:[{q:"Wie gewinnt man typischerweise ein Tempo in der Eröffnung?",o:["Der Gegner muss eine Figur zweimal ziehen, während man selbst neu entwickelt","Indem man selbst möglichst viele Bauernzüge macht","Tempo lässt sich im Schach nicht gewinnen"],c:0}]},{id:"opening-deep:repertoire",level:"Level 14: Eröffnungsverständnis",title:"Ein kleines Eröffnungsrepertoire aufbauen",teach:[["Tiefe vor Breite","Es ist sinnvoller, wenige Eröffnungen wirklich gut zu verstehen als viele nur oberflächlich zu kennen — Verständnis der entstehenden Stellungstypen zählt mehr als auswendig gelernte Zugfolgen."],["Zu den eigenen Prinzipien passend wählen","Wähle Eröffnungen, die zu deinem Spielstil passen: Magst du offene, taktische Stellungen, passen offene Spiele besser als geschlossene Systeme, und umgekehrt."],["Beide Farben abdecken","Ein sinnvolles erstes Repertoire braucht mindestens eine Antwort auf 1.e4, eine auf 1.d4, sowie eine eigene erste Zugwahl mit Weiß — mehr braucht es am Anfang wirklich nicht."]],quiz:[{q:"Was ist am Anfang wichtiger: viele Eröffnungen oberflächlich, oder wenige tief verstehen?",o:["Wenige Eröffnungen wirklich gut verstehen","Möglichst viele verschiedene Eröffnungen kennen","Eröffnungswissen spielt keine Rolle"],c:0}]},{id:"opening-deep:out-of-book",level:"Level 14: Eröffnungsverständnis",title:"Wenn der Gegner die Theorie verlässt",teach:[["Keine Panik","Weicht der Gegner von bekannten Eröffnungszügen ab, heißt das nicht automatisch, dass er einen starken Zug gefunden hat — oft ist es genau umgekehrt."],["Zurück zu den Prinzipien","Kennst du die konkrete Fortsetzung nicht mehr, hilft der Rückgriff auf die Grundprinzipien aus Level 5: Zentrum, Entwicklung, Königssicherheit — sie gelten unabhängig von jeder auswendig gelernten Variante."],["Den Fehler bestrafen","Verstößt der abweichende Zug gegen ein Grundprinzip (z. B. ein unnötiger Randbauernzug oder eine zu frühe Damenentwicklung), lohnt es sich oft besonders, genau das konsequent auszunutzen."]],quiz:[{q:"Was hilft am meisten, wenn der Gegner von bekannter Theorie abweicht?",o:["Auf die Grundprinzipien (Zentrum, Entwicklung, Königssicherheit) zurückgreifen","Sofort resignieren, weil man die Theorie nicht mehr kennt","Zufällig irgendeinen Zug spielen"],c:0}]},{id:"advanced-endgame:key-squares",level:"Level 15: Fortgeschrittene Endspiele",title:"Kritische Felder im Bauernendspiel",teach:[["Mehr als nur Opposition",'Über die Opposition hinaus gibt es für jede Bauernstellung bestimmte "kritische Felder" — erreicht der angreifende König eines davon (meist mit dem Zugrecht des Gegners), gewinnt der Bauer garantiert.'],["Faustregel für einen Bauern auf der 5. Reihe","Steht ein Bauer auf der 5. (oder 6.) Reihe, gibt es sechs kritische Felder: die drei Felder direkt vor ihm (eine Reihe weiter) und die drei Felder zwei Reihen vor ihm. Bei einem Bauern auf der 2., 3. oder 4. Reihe sind es nur die drei Felder zwei Reihen vor ihm. (Randbauern sind eine Ausnahme.)"],["Warum das praktisch hilft","Statt jede Variante einzeln durchzurechnen, reicht oft ein Blick: Steht mein König schon auf einem kritischen Feld (oder kann er es mit Tempo erreichen)? Das beantwortet die Gewinnfrage meist sofort."]],quiz:[{q:'Was verrät ein Blick auf die "kritischen Felder"?',o:["Ob der Bauer bei richtigem Spiel gewinnt, ohne jede Variante einzeln durchrechnen zu müssen","Welche Eröffnung man spielen sollte","Nichts, das Konzept ist rein theoretisch ohne praktischen Nutzen"],c:0}]},{id:"advanced-endgame:bridge-principle",level:"Level 15: Fortgeschrittene Endspiele",title:"Das Brücken-Prinzip im Turmendspiel",teach:[["Das Grundproblem","Steht dein Bauer kurz vor der Umwandlung, aber dein eigener König steht ihr im Weg, während der gegnerische Turm von der Seite ständig Schach bietet, brauchst du eine Methode, die Schachgebote abzuschirmen."],["Die Lösung: eine Brücke bauen","Der eigene Turm stellt sich auf eine mittlere Reihe (oft die 4.) — von dort kann er später als Deckung zwischen den eigenen König und die gegnerischen Schachgebote geschoben werden, wie eine Brücke."],["Warum das ein Klassiker ist","Diese Technik (die Ausgangsstellung heißt nach dem spanischen Schachautor Lucena, 15. Jh., „Lucena-Stellung“) ist eines der wichtigsten Turmendspiel-Motive überhaupt — wer sie kennt, gewinnt viele sonst schwierige Bauern-vor-der-Umwandlung-Stellungen sicher."]],quiz:[{q:'Wofür dient die "Brücke" mit dem eigenen Turm?',o:["Sie schirmt den eigenen König später vor Schachgeboten des gegnerischen Turms ab","Sie verhindert, dass der eigene Bauer sich bewegt","Sie hat nichts mit Turmendspielen zu tun"],c:0}]},{id:"advanced-endgame:third-rank-defense",level:"Level 15: Fortgeschrittene Endspiele",title:"Verteidigung von der Seite und von hinten",teach:[["Das Verteidigungsprinzip","Verteidigt man gegen einen weit fortgeschrittenen gegnerischen Freibauern, ist es oft entscheidend, den gegnerischen König von der Seite abzuschneiden (auf einer bestimmten Linie) UND den eigenen Turm so zu postieren, dass er den Bauern von hinten unter Dauerdruck hält."],['Warum "von hinten" so wirksam ist',"Ein Turm hinter einem gegnerischen Freibauern (auf derselben Linie) bedroht ihn bei jedem weiteren Vorrücken erneut — der Bauer kann sich dem Druck praktisch nie entziehen."],["Geduld ist Teil der Technik","Diese Verteidigungsstellungen halten oft auch dann noch remis, wenn der Gegner scheinbar drückend im Vorteil ist — die Technik verlangt aber genaues, geduldiges Spiel, keine Abkürzungen."]],quiz:[{q:"Warum ist ein Turm HINTER einem gegnerischen Freibauern so wirksam?",o:["Er bedroht den Bauern bei jedem weiteren Vorrücken erneut","Türme dürfen nur von vorne angreifen","Das hat keinen besonderen Effekt"],c:0}]},{id:"advanced-endgame:bishop-vs-knight",level:"Level 15: Fortgeschrittene Endspiele",title:"Läufer- gegen Springerendspiele",teach:[["Der Läufer in offenen Stellungen","In offenen Endspielen mit Bauern auf beiden Flügeln ist der Läufer meist im Vorteil — seine große Reichweite über das ganze Brett zählt hier mehr als die Sprungkraft des Springers."],["Der Springer in geschlossenen/blockierten Stellungen","Sind viele Bauern blockiert oder die Stellung insgesamt geschlossen, kann der Springer im Vorteil sein — er springt über Blockaden hinweg, während der Läufer an ihnen hängen bleibt."],["Bauern auf nur einem Flügel","Stehen alle Bauern auf nur einer Brettseite, hilft dem Läufer seine große Reichweite weniger — hier sind Läufer- und Springerendspiele oft ausgeglichener als die Grundregel vermuten lässt."]],quiz:[{q:"Wann ist ein Springer einem Läufer im Endspiel oft überlegen?",o:["In geschlossenen/blockierten Stellungen, wo er über Hindernisse springen kann","Immer, der Springer ist grundsätzlich stärker","Nur wenn beide Seiten dieselbe Anzahl Bauern haben"],c:0}]},{id:"game-review:use-analysis-feature",level:"Level 16: Partieanalyse als Fähigkeit",title:"Deine eigenen Partien analysieren",teach:[["Die eingebaute Funktion nutzen",'Nach jeder beendeten Partie im freien Spiel kannst du direkt "Partie analysieren" antippen — die App vergleicht dann jeden deiner Züge mit dem materiell/stellungsmäßig bestmöglichen Zug an dieser Stelle.'],["Warum das wertvoller ist als reines Spielen","Ohne Analyse wiederholst du möglicherweise dieselben Fehler in jeder neuen Partie — mit Analyse siehst du sie schwarz auf weiß und kannst gezielt daran arbeiten."],["Nicht nur auf die Fehler schauen",'Achte in der Analyse auch darauf, WELCHE deiner Züge als "gut" durchgingen — zu verstehen, was du bereits richtig machst, ist genauso wertvoll wie Fehler zu finden.']],quiz:[{q:"Was vergleicht die Partieanalyse-Funktion bei jedem Zug?",o:["Deinen gespielten Zug mit dem stellungsmäßig bestmöglichen Zug an dieser Stelle","Nur die Gesamtzahl der Züge der Partie","Deine Bedenkzeit pro Zug"],c:0}]},{id:"game-review:key-moments",level:"Level 16: Partieanalyse als Fähigkeit",title:"Schlüsselmomente einer Partie erkennen",teach:[["Nicht jeder Zug ist gleich wichtig","In den meisten Partien gibt es nur wenige wirklich entscheidende Momente — der Rest sind normale, solide Züge. Genau diese wenigen Schlüsselmomente lohnt es sich, besonders genau zu untersuchen."],["Woran man sie erkennt","Schlüsselmomente sind oft Stellungen kurz vor einem großen Materialwechsel, einem Angriffsbeginn, oder dem Übergang von einer Spielphase zur nächsten (Eröffnung→Mittelspiel, Mittelspiel→Endspiel)."],['Die "was wäre wenn"-Frage',"An einem Schlüsselmoment lohnt es sich zu fragen: Welche anderen Kandidatenzüge (siehe Level Berechnung) standen hier noch zur Verfügung, und wie hätte sich die Partie dann wohl entwickelt?"]],quiz:[{q:'Woran erkennt man einen "Schlüsselmoment" in einer Partie?',o:["Kurz vor großen Materialwechseln, Angriffsbeginn oder Phasenübergängen","An jedem einzelnen Zug gleichermaßen","Nur am allerletzten Zug der Partie"],c:0}]},{id:"game-review:learn-from-mistakes",level:"Level 16: Partieanalyse als Fähigkeit",title:"Aus eigenen Fehlern systematisch lernen",teach:[["Muster statt Einzelfälle","Ein einzelner Fehler ist meist nicht so wichtig wie ein wiederkehrendes Muster — verlierst du wiederholt Material durch dieselbe Art von Übersehen (z. B. immer wieder Gabeln), lohnt sich gezieltes Üben genau dieses Motivs."],["Der Bezug zu deinem Fortschritt","Genau dafür gibt es das Skill-Tracking im Lernpfad: Zeigt sich in mehreren Partien dieselbe Schwäche, verrät dir das direkt, welches Level oder welche Lektion sich jetzt am meisten lohnt."],["Fehler gehören zum Lernen dazu","Niemand spielt fehlerfrei — auch sehr starke Spieler analysieren ihre eigenen Partien und finden dort regelmäßig Verbesserungspotenzial. Das ist normal, kein Zeichen von Schwäche."]],quiz:[{q:"Was ist wertvoller: ein einzelner Fehler oder ein wiederkehrendes Fehlermuster?",o:["Ein wiederkehrendes Muster — es zeigt, wo gezieltes Üben sich am meisten lohnt","Ein einzelner Fehler ist immer wichtiger","Fehler zu analysieren bringt grundsätzlich nichts"],c:0}]},{id:"game-review:close-the-loop",level:"Level 16: Partieanalyse als Fähigkeit",title:"Von der Analyse zum nächsten Lernschritt",teach:[["Der Kreis schließt sich","Eine Partie spielen → analysieren → eine Schwäche erkennen → die passende Lektion im Lernpfad wiederholen oder vertiefen → die nächste Partie besser spielen. Das ist der eigentliche Sinn hinter jedem Level, das du gelernt hast."],["Der Tagesplan hilft dabei",'Die "Heute"-Karte auf der Lernpfad-Startseite ist genau für diesen Kreislauf gedacht — sie schlägt dir vor, wo es sich als Nächstes lohnt weiterzumachen, statt dass du das jedes Mal selbst entscheiden musst.'],["Das eigentliche Ziel",'Am Ende geht es nicht darum, alle Level einmal "abgehakt" zu haben — sondern darum, mit jeder Partie und jeder Analyse ein kleines Stück besser zu verstehen, warum ein Zug funktioniert oder eben nicht.']],quiz:[{q:"Was ist der eigentliche Sinn hinter Partie → Analyse → Lernpfad → nächste Partie?",o:["Gezielt an den eigenen Schwächen arbeiten, statt dieselben Fehler zu wiederholen","Möglichst schnell alle Level abzuhaken","Die Partieanalyse hat keinen Bezug zum Lernpfad"],c:0}]}];export{e as CHESS};
